ger(){return"\u10d7\u10e3 \u10d7\u10e5\u10d5\u10d4\u10dc \u10e8\u10d4\u10e5\u10db\u10d4\u10dc\u10d8\u10d7 \u10d0\u10dc\u10d2\u10d0\u10e0\u10d8\u10e8\u10d8 Edhomy-\u10e8\u10d8, \u10e8\u10d4\u10d2\u10d8\u10eb\u10da\u10d8\u10d0\u10d7 \u10e8\u10d4\u10ee\u10d5\u10d8\u10d3\u10d4\u10d7 \u10d5\u10d8\u10d3\u10d4\u10dd \u10e8\u10d4\u10ee\u10d5\u10d4\u10d3\u10e0\u10d4\u10d1\u10d6\u10d4"},
gdh(){return"\u10e9\u10d0\u10e2\u10d5\u10d8\u10e0\u10d7\u10d5\u10d0"},
gdF(a){return"\u10d9\u10d0\u10d5\u10e8\u10d8\u10e0\u10d8"},
gdC(){return"\u10d0\u10e0\u10d0\u10e4\u10d4\u10e0\u10d8 \u10d8\u10dc\u10e2\u10d4\u10e0\u10dc\u10d4\u10e2\u10d8\u10e1 \u10d9\u10d0\u10d5\u10e8\u10d8\u10e0\u10d8. \u10d2\u10d7\u10ee\u10dd\u10d5\u10d7, \u10d2\u10d0\u10d3\u10d0\u10d0\u10db\u10dd\u10ec\u10db\u10dd\u10d7 \u10d7\u10e5\u10d5\u10d4\u10dc\u10d8 \u10d9\u10d0\u10d5\u10e8\u10d8\u10e0\u10d8"},
