geD(){return"\u0425\u044d\u0440\u044d\u0433\u043b\u044d\u0433\u0447\u0438\u0439\u043d \u043d\u044d\u0440 \u0431\u043e\u043b\u043e\u043d \u043d\u0443\u0443\u0446 \u04af\u0433"},
geG(){return"\u0425\u044d\u0440\u044d\u0433\u043b\u044d\u0433\u0447\u0438\u0439\u043d \u043d\u044d\u0440\u044d\u044d \u044d\u043d\u0434 \u0431\u0438\u0447\u043d\u044d \u04af\u04af"},
ge7(){return"\u041d\u0443\u0443\u0446 \u04af\u0433\u044d\u044d \u044d\u043d\u0434 \u0431\u0438\u0447\u043d\u044d \u04af\u04af"},
gdD(a){return"\u0411\u0430\u0442\u0430\u043b\u0433\u0430\u0430\u0436\u0443\u0443\u043b\u0430\u0445"},
gez(){return"\u041d\u0443\u0443\u0446 \u04af\u0433 \u044d\u0441\u0432\u044d\u043b \u0445\u044d\u0440\u044d\u0433\u043b\u044d\u0433\u0447\u0438\u0439\u043d \u043d\u044d\u0440 \u0431\u0443\u0440\u0443\u0443 \u0431\u0430\u0439\u043d\u0430. \u0414\u044d\u044d\u0434 \u0443\u0434\u0438\u0440\u0434\u043b\u0430\u0433\u0430\u0430\u0441\u0430\u0430 \u0445\u043e\u043b\u0431\u043e\u043e \u0431\u0430\u0440\u0438\u043d\u0430 \u0443\u0443"},
