gdj(){return"\u042d\u043d\u044d \u0445\u0430\u0439\u043b\u0442\u0430\u0430\u0440 \u043c\u044d\u0434\u044d\u044d\u043b\u044d\u043b \u043e\u043b\u0434\u0441\u043e\u043d\u0433\u04af\u0439"},
gdL(){return"\u0413\u0430\u0440\u0447\u0438\u0433 \u0451\u0441\u043e\u043e\u0440 \u043d\u044c \u044d\u0440\u044d\u043c\u0431\u044d\u043b\u044d\u0445"},
gdK(){return"\u0422\u043e\u0434\u043e\u0440\u0445\u043e\u0439\u043b\u043e\u043b\u0442 \u0451\u0441\u043e\u043e\u0440 \u043d\u044c \u044d\u0440\u044d\u043c\u0431\u044d\u043b\u044d\u0445"},
gex(){return"\u041d\u044d\u0440\u044d\u044d\u0440 \u043d\u044c \u044d\u0440\u044d\u043c\u0431\u044d\u043b\u044d\u0445"},
gey(){return"\u0410\u043b\u0431\u0430\u043d \u0442\u0443\u0448\u0430\u0430\u043b\u0430\u0430\u0440 \u043d\u044c \u044d\u0440\u044d\u043c\u0431\u044d\u043b\u044d\u0445"},
