gdE(){return"\u0425\u043e\u043b\u0431\u043e\u0436 \u0431\u0430\u0439\u043d\u0430"},
gcG(){return"\u0418\u043b\u04af\u04af"},
gcF(){return"\u0411\u0430\u0433\u0430"},
ge2(){return"\u041e\u0440\u043e\u043b\u0446\u043e\u0433\u0447\u0438\u0434"},
ge9(){return"\u0425\u0430\u0440\u0430\u0445"},
